with d as (select value r from jsonb_array_elements($q$[{"notes":["Make ahead: cook the barbacoa the day before, then shred and reheat gently in the braising liquid. Keeps in the fridge for up to 3 days.","Serve on warm flour tortillas with diced onion, fresh coriander and lime wedges.","This is a weekend cook: take your time and let the low heat do the work.","Food safety: Cook whole cuts of beef, lamb and pork to at least 63°C in the thickest part, then rest for 3 minutes; cook pork and any rolled or stuffed cuts until the juices run clear."],"steps":[{"text":"Heat the oven to 120°C. Toast the dried guajillo and chipotle chillies in a dry pan for 2 minutes until fragrant, then transfer to a bowl and cover with hot water. Let sit for 15 minutes until soft."},{"text":"Drain the rehydrated chillies, then blitz them in a blender with garlic, cumin, oregano, cloves, beef stock, vinegar and salt until smooth. Strain through a sieve if you want a silky paste; for rustic texture, leave it coarse."},{"text":"Pat the brisket dry. Rub all over with the chilli paste until well coated. Wrap tightly in agave or banana leaves and then in foil, sealing the edges."},{"text":"Place the wrapped brisket in a heavy-based pot or Dutch oven. Cover and braise in the oven for 7 to 8 hours, until the meat shreds easily with a fork."},{"text":"Remove from the oven and let rest for 15 minutes. Unwrap carefully, watch out for steam, and shred the beef using two forks, pulling it apart along the grain."},{"text":"Strain the braising liquid into a jug. Skim any fat from the surface and season with salt to taste. Toss the shredded beef with a few tbsp of the braising liquid to keep it moist."}],"id":"9e11ad50-966b-46ee-8321-230475ae1158"},{"notes":["Make it ahead and reheat gently with a splash of milk, it keeps for 3 days in the fridge.","If you can't find broken rice, crush short-grain white rice coarsely with your hands or a rolling pin before cooking."],"id":"b34cfbc0-1a3a-40ae-a5c3-d4644fe171d8"},{"notes":["Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"id":"63b705ec-da62-40f7-814d-589f65673dc4"},{"notes":["Serve with white rice, collard greens or a simple slaw to cool the heat.","The frying pan must be smoking hot, don't skip this step or you won't get that proper blackened crust.","Swap catfish for any firm white fish fillet.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"steps":[{"text":"Mix paprika, cayenne, cumin, onion powder, garlic powder, thyme, oregano, black pepper and salt in a shallow dish."},{"text":"Pat the catfish fillets dry with paper towels. Coat both sides generously with the spice mixture, pressing it on so it sticks."},{"text":"Heat the oil in a cast-iron frying pan over high heat until it's smoking and a drop of water beads and rolls across the surface, about 2 minutes."},{"text":"Add the butter and swirl it through the hot oil. When it's foaming and just starting to brown, lay the catfish fillets in the frying pan, they should sizzle hard."},{"text":"Sear without moving them for 3 to 4 minutes, until the crust is dark brown and charred. Flip carefully."},{"text":"Sear the other side for another 2 to 3 minutes, until the fish is cooked through and flakes easily with a fork. Serve hot."}],"id":"69c02bf5-fc98-438e-b85d-e706661bea2c"},{"notes":["Kopytka can be made ahead: shape and boil them, then store in the fridge for up to 2 days. Toss with the mushrooms and onions to warm through.","The dough should stay slightly loose, too much flour and the kopytka become heavy. If it's very sticky, dust with a little more flour, but resist the urge to knead.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Boil the potato in salted water until tender, about 12 minutes. Drain well and pass through a ricer while still hot into a large bowl."},{"text":"Add the flour, egg, and salt to the potato. Mix gently with your hands until just combined, it should feel a little soft and slightly sticky, not smooth. Don't overwork it."},{"text":"Bring a large pot of salted water to a boil. Dust the work surface lightly with flour. Break off a piece of dough about the size of a walnut, roll it roughly into a stick about 5 cm long, and press gently with your thumb to make a small indent (this is the little hoof). Drop each kopytka into the boiling water as you shape them. They will sink, then float to the surface; cook for 2–3 minutes after they float. Drain and spread on a tray to cool."},{"text":"While the kopytka cook, heat the oil in a large pan over medium-high heat. Add the mushrooms and fry, stirring often, until they are golden and any liquid has evaporated, about 8 minutes. Transfer to a plate."},{"text":"Lower the heat to medium and add the onions to the same pan. Cook, stirring now and then, until they are soft and deeply golden, about 12 minutes. Add the garlic and thyme, if using, and cook for another minute."},{"text":"Return the mushrooms to the pan with the onions. Add the drained kopytka and toss gently until everything is warm and coated. Season with salt and black pepper. Serve hot."}],"id":"eb4a1e90-4a18-4dbf-bf7d-8edb3843ddda"},{"notes":["Fresh masa is best, but masa harina (corn flour) works well too: use about 125 g mixed with a little warm water to a smooth paste.","Oaxacan chocolate is grainy and textured, sold as tablets, seek it in Latin or Mexican markets, or use good dark chocolate with a tiny pinch of ground almond added.","A molinillo whisk creates the traditional frothy top, but a regular whisk does the job."],"id":"99a6c6fb-a4f3-40e7-8372-0b057cbfd4e9"},{"steps":[{"text":"If using dried noodles, cook in boiling salted water until just tender, drain well and spread on a tray to cool. Fresh noodles can be used as they are."},{"text":"Heat the oil in a large wok or wide frying pan over high heat. When shimmering, add the sliced garlic and ginger. Stir-fry for about 1 minute until fragrant but not brown."},{"text":"Add the water spinach and toss constantly for 2–3 minutes until it begins to wilt but the stems still have a gentle firmness."},{"text":"Add the cooled noodles to the wok, breaking them apart gently with chopsticks or tongs as you toss. Stir-fry for 2–3 minutes until heated through."},{"text":"Pour the soy sauce and rice vinegar over the noodles and toss well for another minute, letting the flavours coat everything evenly."},{"text":"Taste and season with salt and black pepper. If you like heat, sprinkle with dried chilli flakes."},{"text":"Serve at once, while the noodles are still warm and the spinach stems hold their slight crispness."}],"id":"bbdb520c-b7f5-4aa1-a086-4e2b600a14e9"},{"notes":["Make it a day ahead if you like, the flavours deepen overnight. Reheat gently on the stove.","The scotch bonnet stays whole while cooking so you control the heat. Leave it out if you prefer a gentler dish."],"id":"aa6071dd-3828-4d92-903c-62891d97aab4"},{"notes":["If you don't have a pudding basin, a 1.5-litre heatproof bowl wrapped in foil will work, though you may need to adjust the steaming time slightly.","Leftovers can be reheated gently in the steamer for 30 minutes, or covered in foil in a 150°C oven for about 45 minutes.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"steps":[{"text":"Heat the oil in a large pan over medium-high heat. Season the beef with salt and pepper. Brown the meat in batches, about 3 minutes per batch, until well coloured on all sides. Set aside."},{"text":"In the same pan, cook the onion until soft, about 5 minutes. Add the garlic and tomato paste, stir well, and cook for 2 minutes more."},{"text":"Return the beef to the pan. Pour in the ale and stock, scraping the bottom of the pan. Add the bay leaves and thyme. Bring to a simmer, then remove from heat and leave to cool completely, at least 1 hour. The filling needs to be cold before you add it to the pastry."},{"text":"While the filling cools, make the suet crust. Mix the flour and salt in a large bowl. Add the suet and stir until it's distributed evenly. Add the cold water a little at a time, stirring with a knife until a soft, slightly sticky dough forms. Knead gently until just combined; don't overwork it."},{"text":"Lightly flour a work surface. Roll out two-thirds of the dough into a circle about 40 cm across and 5 mm thick. It should be large enough to line a 1.5-litre pudding basin with some hanging over the edge."},{"text":"Use this large circle to line the pudding basin, leaving the excess hanging over the rim."},{"text":"Strain the cooled filling, reserving the liquid. Discard the bay leaves and thyme. Spoon the beef and onions into the lined basin, then pour in enough of the reserved liquid to come halfway up the filling (about 200 ml). Save the rest for serving."},{"text":"Roll out the remaining dough into a circle about 25 cm across, 5 mm thick. Lay this on top of the filling. Fold the overhanging pastry inward over the lid, pressing down to seal."},{"text":"Cover the pudding with a pleated piece of baking paper (the pleat allows for expansion), then a pleated piece of foil. Tie both down with string under the lip of the basin."},{"text":"Place the pudding basin in a large pot and add enough boiling water to come halfway up the sides of the basin. Cover the pot with a lid. Steam for 3 hours, checking every 45 minutes and topping up the water if needed, it should stay at the same level."},{"text":"Carefully remove the pudding from the pot. Let it rest for 10 minutes. Warm the reserved liquid in a small pan."},{"text":"Turn the pudding out onto a warm plate or serving bowl. Serve with the warmed gravy poured over the top, and mashed potato on the side."}],"id":"9309bc2a-9f30-4f85-9cfc-d2554c594a88"},{"notes":["Make the dough the day before if it suits you, cold dough ferments gently overnight. Shape and prove the next morning.","If you grind whole cardamom pods yourself, use about 1½ tsp of pods; they're more fragrant than pre-ground.","Semlor are best eaten the day they're made. Store in an airtight container for up to a day, but the bun will soften.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"5271f5da-2631-497e-9617-ad94681684c1"},{"notes":["If you can't find khoya, reduce 500 ml milk slowly in a heavy pan until it becomes a thick paste (about 30 minutes), then use that instead, it will give you more authentic flavour and texture.","For a softer sandesh (Arnab's preference), use only 50 g khoya and don't chill for as long; for a firmer set (his wife's way), add an extra 25 g khoya.","Regional variations: try adding a few strands of saffron, a tablespoon of mango pulp, or a teaspoon of rose water instead of cardamom, the arguments are endless and that's rather the point."],"steps":[{"text":"Bring the milk to a rolling boil in a heavy-bottomed pan over high heat, until it foams up and rises towards the rim. Once it reaches a full boil, remove from the heat."},{"text":"Add the yoghurt slowly, stirring gently. The milk will curdle immediately. Let it sit for 2 minutes, then pour through a fine sieve lined with muslin cloth, collecting the whey in a bowl beneath. Let it drain for 5 minutes."},{"text":"Gather the corners of the muslin and hang it to drain for 30 minutes until the paneer is quite dry but still soft."},{"text":"Turn the paneer into a bowl and crumble it finely with your fingertips. Add the khoya, sugar, cardamom seeds (discarding the husks), and salt. Mix gently but thoroughly until the mixture just holds together."},{"text":"Divide the mixture into 12 portions and shape each into a small smooth ball or oval with damp hands. You can press each into a small mould if you have one, then tap it out onto a plate."},{"text":"Chill for at least 15 minutes before serving. Store in an airtight container in the fridge for up to 3 days."}],"id":"08f16912-d659-445a-864b-6b291d535ad3"},{"notes":["Sole is the classic choice, but halibut, plaice or any firm white fish works. You can also cook fillets, they'll need only 1–2 minutes per side.","The brown butter is everything. Don't skip it or rush it; the aroma tells you when it's ready."],"steps":[{"text":"Pat the sole dry with paper towels. Season inside and out with salt and pepper."},{"text":"Spread the flour on a shallow plate. Lightly coat both sides of each fish, shaking off the excess."},{"text":"Heat the oil in a large frying pan over medium-high heat until shimmering."},{"text":"Lay the sole in the pan and cook, without moving, for 2–3 minutes until the skin is golden and crisp. Flip and cook the other side for 2–3 minutes until cooked through."},{"text":"Transfer the fish to a warm plate. Reduce the heat to medium, add the butter to the same pan, and let it melt and brown, swirling gently, for 1–2 minutes until it smells nutty and turns golden."},{"text":"Pour the brown butter over the fish, squeeze lemon juice over the top (it will sizzle briefly), scatter with parsley if using, and serve at once while the butter is still hot and nutty."}],"id":"20bc01fb-f1da-4793-9da1-9c93d20fd7b4"},{"notes":["For extra richness, some cooks stir in a spoonful of crème fraîche or Greek yoghurt just before serving.","Make this ahead and reheat gently, the flavour deepens overnight."],"id":"11ee35b8-7029-4f2c-9c05-30fe579fb588"},{"notes":["Kalua pork keeps well in the fridge for 4 days, and freezes for up to 3 months. Reheat gently with a splash of water.","Serve with rice, cabbage slaw and gravy for a real plate lunch, or use it for musubi.","The longer you cook it, the more tender it gets, even 8 or 9 hours won't hurt.","Food safety: Cook fresh pork to at least 70°C in the thickest part."],"id":"ee778302-0727-480f-a85c-34ea49898277"},{"notes":["Make the gochujang butter ahead and keep it in a pot in the fridge; it'll come together faster in the morning.","Use leftover rice from the night before, or make a quick batch while you wait for the egg to fry.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system. Cool any leftover rice quickly and refrigerate it within an hour; reheat it until steaming hot."],"id":"932fe6b4-6b1a-44b4-a5c6-5bd6c18b1928"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;